  1	/**
  2	 * Tests for WP-010: GUI Credential-Missing Error Display.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1 — When a repository's clone error contains the credential-missing
  6	 *          sentinel text ("requires a credential for host"), the workspace
  7	 *          detail view shows a "Missing Credential" badge instead of the
  8	 *          generic "No data" badge.
  9	 *   AC2 — The "Missing Credential" badge links to the repository detail view
 10	 *          (#/repositories/:id) where the user can select a credential.
 11	 *   AC3 — Non-credential clone errors continue to display as the generic
 12	 *          "No data" badge (no regression in existing error display).
 13	 *   AC4 — The credential-missing error detection uses the sentinel text
 14	 *          ("requires a credential for host") from the orchestrator error
 15	 *          messages (WP-007).
 16	 *
 17	 * Additional toast message tests:
 18	 *   T1  — When all failures are credential-related, the toast mentions
 19	 *          "credential errors" and the affected repository IDs.
 20	 *   T2  — When failures are a mix of credential and non-credential, the
 21	 *          toast distinguishes them.
 22	 *   T3  — When all failures are non-credential, the original toast message
 23	 *          is shown unchanged.
 24	 *
 25	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 26	 * Run individually with:
 27	 *   node --test gui/public/js/views/workspace-detail.credential-error.test.mjs
 28	 */
 29	
 30	import { test, beforeEach } from 'node:test';
 31	import assert from 'node:assert/strict';
 32	import { JSDOM } from 'jsdom';
 33	
 34	// ---------------------------------------------------------------------------
 35	// jsdom setup — install globals before any module is loaded
 36	// ---------------------------------------------------------------------------
 37	
 38	const dom = new JSDOM(
 39	    '<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>',
 40	    { url: 'http://localhost/' },
 41	);
 42	
 43	const { window } = dom;
 44	
 45	globalThis.document    = window.document;
 46	globalThis.window      = window;
 47	globalThis.location    = window.location;
 48	globalThis.HTMLElement = window.HTMLElement;
 49	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 50	
 51	// Stub setInterval / clearInterval so the polling loop never fires and the
 52	// process exits cleanly after tests complete.
 53	let _intervalId = 0;
 54	const _intervals = new Map();
 55	globalThis.setInterval = (fn, delay) => {
 56	    const id = ++_intervalId;
 57	    _intervals.set(id, { fn, delay });
 58	    return id;
 59	};
 60	globalThis.clearInterval = (id) => {
 61	    _intervals.delete(id);
 62	};
 63	
 64	// ---------------------------------------------------------------------------
 65	// Minimal fetch mock (required by api.js)
 66	// ---------------------------------------------------------------------------
 67	
 68	globalThis.fetch = async () => ({
 69	    status: 200,
 70	    ok: true,
 71	    statusText: 'OK',
 72	    headers: { get: () => 'application/json' },
 73	    json: async () => ({}),
 74	});
 75	
 76	// ---------------------------------------------------------------------------
 77	// Import dependencies and patch api
 78	// ---------------------------------------------------------------------------
 79	
 80	const { api } = await import('../api.js');
 81	
 82	// Credential-missing sentinel — must match CREDENTIAL_MISSING_SENTINEL in
 83	// workspace-detail.js and the error message template in the orchestrators.
 84	const SENTINEL = 'requires a credential for host';
 85	
 86	// Setup spy — controls what the API returns after workspace setup.
 87	const setupCalls = [];
 88	let setupResult  = { results: [] };
 89	api.workspaces.setup = async (projectId, wid) => {
 90	    setupCalls.push({ projectId, wid });
 91	    return setupResult;
 92	};
 93	
 94	// Default stubs for the remaining api calls used by renderWorkspaceDetail.
 95	api.workspaces.get    = async () => ({
 96	    Id: 'DEV', id: 'DEV', Description: '', initialized: false, folderPath: '/tmp/dev',
 97	});
 98	api.workspaces.health = async () => ({ healthy: true, issues: [] });
 99	api.workspaces.launch = api.workspaces.launch || {};
100	api.workspaces.launch.githubDesktop = async () => ({ success: true });

101	api.workspaces.launch.vscode        = async () => ({ success: true });
102	api.projects.get      = async () => ({
103	    Id: 'my-project',
104	    Repositories: ['repo-alpha', 'repo-beta'],
105	});
106	
107	// Status refresh: by default, no repos have status data yet.
108	let statusMapOverride = {};
109	api.status.refresh = async () => statusMapOverride;
110	api.status.get     = async () => statusMapOverride;
111	
112	if (!api.config)          api.config          = {};
113	if (!api.config.polling)  api.config.polling  = {};
114	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
115	if (!api.config.webserverUrl) api.config.webserverUrl = {};
116	api.config.webserverUrl.get = async () => ({ webserverUrl: '' });
117	
118	const { renderWorkspaceDetail } = await import('./workspace-detail.js');
119	
120	// Local re-declaration — see gui/public/js/utils/dom.js for the canonical export.
121	// Static imports from ../utils/dom.js cannot be resolved in this Node.js jsdom harness.
122	function clearElement(el) { while (el.firstChild) el.removeChild(el.firstChild); }
123	
124	// ---------------------------------------------------------------------------
125	// Render helper
126	// ---------------------------------------------------------------------------
127	
128	/**
129	 * Render the workspace-detail view and wait for the async bootstrap to settle.
130	 *
131	 * We poll until a `<table>` or `.workspace-detail-header` element appears, or
132	 * a maximum tick budget is exhausted.
133	 *
134	 * @param {string} [projectId]
135	 * @param {string} [wid]
136	 * @returns {Promise<{ container: HTMLElement, cleanup: function }>}
137	 */
138	async function renderView(projectId = 'my-project', wid = 'DEV') {
139	    const container = window.document.getElementById('app');
140	    clearElement(container);
141	
142	    const cleanup = renderWorkspaceDetail(container, { id: projectId, wid });
143	
144	    await new Promise((resolve) => {
145	        let ticks = 0;
146	        const poll = () => {
147	            ticks++;
148	            if (
149	                container.querySelector('table') ||
150	                container.querySelector('.workspace-detail-header') ||
151	                ticks > 200
152	            ) {
153	                resolve();
154	            } else {
155	                Promise.resolve().then(poll);
156	            }
157	        };
158	        Promise.resolve().then(poll);
159	    });
160	
161	    return { container, cleanup };
162	}
163	
164	/**
165	 * Simulate a setup button click and wait for the DOM to update.
166	 *
167	 * @param {HTMLElement} container
168	 */
169	async function clickSetupAndWait(container) {
170	    const setupBtn = [...container.querySelectorAll('button')]
171	        .find((b) => b.textContent.includes('Setup Workspace'));
172	    assert.ok(setupBtn, 'Setup Workspace button must be present to simulate setup');
173	
174	    setupBtn.click();
175	
176	    // Drain microtask queue — the click handler is async, so we need several
177	    // ticks for the await chain inside the click handler to settle.
178	    for (let i = 0; i < 20; i++) {
179	        await new Promise((r) => Promise.resolve().then(r));
180	    }
181	}
182	
183	// ---------------------------------------------------------------------------
184	// Per-test reset
185	// ---------------------------------------------------------------------------
186	
187	beforeEach(() => {
188	    setupCalls.length   = 0;
189	    setupResult         = { results: [] };
190	    statusMapOverride   = {};
191	    _intervals.clear();
192	    clearElement(document.getElementById('toast-container'));
193	    // Restore default: workspace NOT initialized so the Setup button is present.
194	    api.workspaces.get = async () => ({
195	        Id: 'DEV', id: 'DEV', Description: '', initialized: false, folderPath: '/tmp/dev',
196	    });
197	});
198	
199	// ---------------------------------------------------------------------------
200	// AC1 — "Missing Credential" badge shown when credential error detected
201	// ---------------------------------------------------------------------------
202	
203	test('AC1: setup result with credential-missing sentinel shows "Missing Credential" badge for that repo', async () => {
204	    // repo-alpha fails with the credential sentinel; repo-beta succeeds.
205	    setupResult = {
206	        results: [
207	            { repositoryId: 'repo-alpha', success: false, error: `Repository 'repo-alpha' ${SENTINEL} 'github.com'. Please select a credential in the repository settings.` },
208	            { repositoryId: 'repo-beta',  success: true },
209	        ],
210	    };
211	
212	    const { container, cleanup } = await renderView();
213	    try {
214	        await clickSetupAndWait(container);
215	
216	        const tbody = container.querySelector('tbody');
217	        assert.ok(tbody, 'status table tbody should exist');
218	
219	        // repo-alpha row should have the credential badge.
220	        const alphaRow = tbody.querySelector('tr[data-repo-id="repo-alpha"]');
221	        assert.ok(alphaRow, 'repo-alpha row should be present');
222	
223	        const badgeWrapper = alphaRow.querySelector('div[data-repo-id="repo-alpha"]');
224	        assert.ok(badgeWrapper, 'badge wrapper should be present');
225	
226	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
227	        assert.ok(credBadge, 'Missing Credential badge (.status-badge-credential) should be present for repo-alpha');
228	        assert.ok(
229	            credBadge.textContent.includes('Missing Credential'),
230	            `badge text should contain "Missing Credential", got: "${credBadge.textContent}"`,
231	        );
232	    } finally {
233	        cleanup();
234	    }
235	});
236	
237	test('AC1: repo with non-credential clone error retains generic "No data" badge', async () => {
238	    // repo-alpha fails with a generic error (not the sentinel).
239	    setupResult = {
240	        results: [
241	            { repositoryId: 'repo-alpha', success: false, error: 'fatal: repository not found' },
242	        ],
243	    };
244	
245	    const { container, cleanup } = await renderView();
246	    try {
247	        await clickSetupAndWait(container);
248	
249	        const tbody = container.querySelector('tbody');
250	        assert.ok(tbody, 'status table tbody should exist');
251	
252	        const alphaRow = tbody.querySelector('tr[data-repo-id="repo-alpha"]');
253	        assert.ok(alphaRow, 'repo-alpha row should be present');
254	
255	        const badgeWrapper = alphaRow.querySelector('div[data-repo-id="repo-alpha"]');
256	        assert.ok(badgeWrapper, 'badge wrapper should be present');
257	
258	        // Must NOT have the credential badge.
259	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
260	        assert.strictEqual(credBadge, null, 'credential badge must NOT be shown for non-credential errors');
261	
262	        // Should still have the generic error badge.
263	        const errorBadge = badgeWrapper.querySelector('.status-badge-error');
264	        assert.ok(errorBadge, 'generic error badge (.status-badge-error) should remain for non-credential errors');
265	    } finally {
266	        cleanup();
267	    }
268	});
269	
270	// ---------------------------------------------------------------------------
271	// AC2 — badge links to #/repositories/:id
272	// ---------------------------------------------------------------------------
273	
274	test('AC2: "Missing Credential" badge href points to #/repositories/:repoId', async () => {
275	    setupResult = {
276	        results: [
277	            { repositoryId: 'repo-alpha', success: false, error: `repo-alpha ${SENTINEL} 'example.com'` },
278	        ],
279	    };
280	
281	    const { container, cleanup } = await renderView();
282	    try {
283	        await clickSetupAndWait(container);
284	
285	        const badgeWrapper = container.querySelector('div[data-repo-id="repo-alpha"]');
286	        assert.ok(badgeWrapper, 'badge wrapper should be present');
287	
288	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
289	        assert.ok(credBadge, 'credential badge should be present');
290	
291	        const href = credBadge.getAttribute('href');
292	        assert.ok(
293	            href && href.includes('#/repositories/repo-alpha'),
294	            `href should point to #/repositories/repo-alpha, got: "${href}"`,
295	        );
296	    } finally {
297	        cleanup();
298	    }
299	});
300	
301	test('AC2: "Missing Credential" badge href URL-encodes the repository ID', async () => {
302	    // Use a repo ID with characters that require encoding.
303	    api.projects.get = async () => ({
304	        Id: 'my-project',
305	        Repositories: ['repo/with spaces'],
306	    });
307	    setupResult = {
308	        results: [
309	            { repositoryId: 'repo/with spaces', success: false, error: `${SENTINEL} 'example.com'` },
310	        ],
311	    };
312	
313	    const { container, cleanup } = await renderView();
314	    try {
315	        await clickSetupAndWait(container);
316	
317	        const badgeWrapper = container.querySelector('div[data-repo-id="repo/with spaces"]');
318	        assert.ok(badgeWrapper, 'badge wrapper should be present for repo with spaces');
319	
320	        const credBadge = badgeWrapper.querySelector('.status-badge-credential');
321	        assert.ok(credBadge, 'credential badge should be present');
322	
323	        const href = credBadge.getAttribute('href');
324	        // encodeURIComponent('repo/with spaces') === 'repo%2Fwith%20spaces'
325	        assert.ok(
326	            href && href.includes('repo%2Fwith%20spaces'),
327	            `href should URL-encode the repo ID, got: "${href}"`,
328	        );
329	    } finally {
330	        cleanup();
331	        // Restore default projects.get stub.
332	        api.projects.get = async () => ({ Id: 'my-project', Repositories: ['repo-alpha', 'repo-beta'] });
333	    }
334	});
335	
336	// ---------------------------------------------------------------------------
337	// AC3 — Non-credential errors are not affected (regression guard)
338	// ---------------------------------------------------------------------------
339	
340	test('AC3: non-credential errors show the original "No data" badge, not the credential badge', async () => {
341	    setupResult = {
342	        results: [
343	            { repositoryId: 'repo-alpha', success: false, error: 'Connection timeout' },
344	            { repositoryId: 'repo-beta',  success: false, error: 'Permission denied (publickey)' },
345	        ],
346	    };
347	
348	    const { container, cleanup } = await renderView();
349	    try {
350	        await clickSetupAndWait(container);
351	
352	        const tbody = container.querySelector('tbody');
353	        const rows  = tbody ? [...tbody.querySelectorAll('tr[data-repo-id]')] : [];
354	        assert.ok(rows.length > 0, 'expected at least one repo row');
355	
356	        for (const row of rows) {
357	            const credBadge = row.querySelector('.status-badge-credential');
358	            assert.strictEqual(
359	                credBadge,
360	                null,
361	                `credential badge must NOT appear for row ${row.dataset.repoId} with non-credential error`,
362	            );
363	        }
364	    } finally {
365	        cleanup();
366	    }
367	});
368	
369	test('AC3: repos that succeed during setup do not get a credential badge', async () => {
370	    setupResult = {
371	        results: [
372	            { repositoryId: 'repo-alpha', success: true },
373	            { repositoryId: 'repo-beta',  success: true },
374	        ],
375	    };
376	
377	    const { container, cleanup } = await renderView();
378	    try {
379	        await clickSetupAndWait(container);
380	
381	        const credBadges = container.querySelectorAll('.status-badge-credential');
382	        assert.strictEqual(
383	            credBadges.length,
384	            0,
385	            'no credential badges should appear when all repos succeed',
386	        );
387	    } finally {
388	        cleanup();
389	    }
390	});
391	
392	// ---------------------------------------------------------------------------
393	// AC4 — Sentinel text detection is exact substring match
394	// ---------------------------------------------------------------------------
395	
396	test('AC4: only errors containing the exact sentinel text trigger the credential badge', async () => {
397	    // Mix: one with sentinel, one without.
398	    setupResult = {
399	        results: [
400	            {

401	                repositoryId: 'repo-alpha',
402	                success: false,
403	                error: `Repository 'repo-alpha' ${SENTINEL} 'github.com'. Please select a credential.`,
404	            },
405	            {
406	                repositoryId: 'repo-beta',
407	                success: false,
408	                error: 'fatal: could not read Username for https://github.com',
409	            },
410	        ],
411	    };
412	
413	    const { container, cleanup } = await renderView();
414	    try {
415	        await clickSetupAndWait(container);
416	
417	        const tbody = container.querySelector('tbody');
418	        assert.ok(tbody);
419	
420	        // repo-alpha: has sentinel → credential badge expected.
421	        const alphaWrapper = tbody.querySelector('div[data-repo-id="repo-alpha"]');
422	        assert.ok(alphaWrapper, 'repo-alpha badge wrapper should exist');
423	        assert.ok(
424	            alphaWrapper.querySelector('.status-badge-credential'),
425	            'repo-alpha should have the credential badge (sentinel present)',
426	        );
427	
428	        // repo-beta: no sentinel → NO credential badge.
429	        const betaWrapper = tbody.querySelector('div[data-repo-id="repo-beta"]');
430	        assert.ok(betaWrapper, 'repo-beta badge wrapper should exist');
431	        assert.strictEqual(
432	            betaWrapper.querySelector('.status-badge-credential'),
433	            null,
434	            'repo-beta must NOT have the credential badge (no sentinel)',
435	        );
436	    } finally {
437	        cleanup();
438	    }
439	});
440	
441	// ---------------------------------------------------------------------------
442	// T1 — Toast message for all-credential failures
443	// ---------------------------------------------------------------------------
444	
445	test('T1: when all clone failures are credential-related, toast mentions "credential errors"', async () => {
446	    setupResult = {
447	        results: [
448	            { repositoryId: 'repo-alpha', success: false, error: `${SENTINEL} 'github.com'` },
449	            { repositoryId: 'repo-beta',  success: false, error: `${SENTINEL} 'gitlab.com'` },
450	        ],
451	    };
452	
453	    const { container, cleanup } = await renderView();
454	    try {
455	        await clickSetupAndWait(container);
456	
457	        const toastContainer = document.getElementById('toast-container');
458	        const toastText = toastContainer ? toastContainer.textContent : '';
459	        assert.ok(
460	            toastText.includes('credential'),
461	            `toast should mention "credential" for credential failures, got: "${toastText}"`,
